namespace Payroll.Shared.Domain;

/// <summary>
/// One uploaded payroll file from one entity. This is the system of record for
/// everything the dashboard displays.
/// </summary>
public class PayrollBatch
{
    /// <summary>Client-facing identifier. Generated by the API, never reused across retries.</summary>
    public Guid Id { get; set; }

    /// <summary>The uploading entity's business identifier. Synthetic, not an authenticated principal -- there is no auth in phase 1.</summary>
    public string EntityId { get; set; } = string.Empty;

    public string OriginalFileName { get; set; } = string.Empty;

    // ---- Blob reference (populated in Phase 2) ----
    public string? BlobContainer { get; set; }
    public string? BlobName { get; set; }
    /// <summary>ETag captured at upload -- lets us detect later tampering or deletion.</summary>
    public string? BlobETag { get; set; }
    public long FileSizeBytes { get; set; }

    /// <summary>Propagated to Service Bus, Application Insights, and every log line. The backbone of end-to-end tracing.</summary>
    public string CorrelationId { get; set; } = string.Empty;

    public BatchStatus Status { get; set; }

    // ---- Processing outcome ----
    public int? ExpectedRows { get; set; }
    public int? ProcessedRows { get; set; }

    /// <summary>How many deliveries this message has taken. Surfaces poison-message behaviour on the dashboard.</summary>
    public int DeliveryCount { get; set; }

    public string? FailureReason { get; set; }
    public string? FailureStage { get; set; }

    // ---- Timeline ----
    public DateTimeOffset CreatedAtUtc { get; set; }
    public DateTimeOffset? QueuedAtUtc { get; set; }
    public DateTimeOffset? StartedAtUtc { get; set; }
    public DateTimeOffset? CompletedAtUtc { get; set; }
    public DateTimeOffset? UpdatedAtUtc { get; set; }

    /// <summary>Wall-clock processing duration, measured by the Function. Exposed as a metric.</summary>
    public double? ProcessingDurationMs { get; set; }

    public ICollection<PayrollResult> Results { get; set; } = new List<PayrollResult>();
}